)

counties_now |>
  dplyr::filter(county %in% focus_counties) |>
  dplyr::mutate(
    county = factor(county, levels = focus_counties),
    sign_grp = factor(
      dplyr::if_else(netmig >= 0, "Net gain", "Net loss"),
      levels = c("Net loss", "Net gain")
    )
  ) |>
  ggplot(aes(x = age_group, y = netmig, fill = sign_grp)) +
  geom_col(width = 0.75) +
  geom_hline(yintercept = 0, colour = "grey30", linewidth = 0.4) +
  facet_wrap(~county, ncol = 4, scales = "free_y") +
  scale_fill_sdo_discrete(drop = FALSE) +
  scale_y_continuous(labels = scales::label_comma(style_positive = "plus")) +
  labs(
