    subtitle = "Vertical scales differ by county so that each pattern's shape is visible",
    x = "Age in 2025",
    y = "Net migration",
    fill = NULL,
    caption = source_caption
  ) +
  theme_sdo_bare() +
  theme(
    legend.position = "top",
    axis.text.x = element_text(angle = 90, vjust = 0.5, hjust = 1, size = 6.5),
    strip.text = element_text(face = "bold")
  )
